sys_script_fix.script:
function updateStoryPointsColumnLabel() {
	var gr = new GlideRecord('sys_dictionary');
	gr.addQuery('name', 'rm_sprint');
	gr.addQuery('element', 'story_points');
	gr.addQuery('column_label', 'Story points').addOrCondition('column_label', 'Total committed points').addOrCondition('column_label', 'Total commited points');
	gr.setLimit(1);
	gr.query();

	if (gr.next()) {
		gr.setValue('column_label', 'Current scope points');

		if (gr.update())
			gs.info('Successfully updated rm_sprint.story_points column label to "Story points"');
		else
			gs.error('Failed to update rm_sprint.story_points column label to "Story points"');
	}
}

updateStoryPointsColumnLabel();
